import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { loadCorePluginRegistry } from '@mokuyoaxis/dsh-iris/plugins';
import { createPanelPluginFixture } from './panel-plugin-fixture.mjs';
import { writeLocalApiTokenFile } from '../../lib/local-api.js';
import { executeConfigCommand } from '../../lib/provider-config-service.js';
import { FLOW_RESULT } from './image-flow-fixture.mjs';

export async function verifyPluginPanelBrowser({ out, dataRoot, chosenRunId, cdp, evaluate, click, wait, chooseToken, readyRun,
  report, save, dimensions, measure, capture, pausedResponses, restart }) {
  const result = report.pluginPanel = { status: 'running', checks: [], actualPaidCalls: 0 };
  const fixture = createPanelPluginFixture(), registry = await loadCorePluginRegistry({ entries: [fixture.entry] });
  const config = path.join(out, 'plugin-provider-settings.json');
  fs.writeFileSync(config, JSON.stringify({ providers: [], assignments: {} }) + '\n', { mode: 0o600 });
  const selection = { pages: ['example.panel.library', 'example.panel.slow', 'example.panel.broken', 'example.panel.module'], settings: ['example.panel.connection'], renderers: ['example.panel.png'] };
  const check = async (name, expression) => { assert.equal(await evaluate(expression), true, name); result.checks.push(name); save(); };
  const library = "document.querySelector('#plugin-page-slot .plugin-surface')?.shadowRoot";
  const settings = "document.querySelector('#plugin-settings-list .plugin-surface')?.shadowRoot";
  const preview = "document.querySelector('#plugin-preview-slot .plugin-surface')?.shadowRoot";
  async function login(session) {
    const token = path.join(out, 'plugin-owner-' + result.checks.length); writeLocalApiTokenFile(token, session.accessToken, dataRoot);
    await cdp('Page.navigate', { url: 'about:blank' }); await cdp('Page.navigate', { url: session.origin + '/#' + chosenRunId });
    await wait(() => evaluate("Boolean(document.documentElement.dataset.theme&&!document.querySelector('#connection').hidden)"), 'plugin login shell');
    await chooseToken(token); await readyRun(chosenRunId);
  }
  try {
    let session = await restart({ pluginRegistry: registry, panelContributions: selection, allowProviderManagement: true, providerConfigPath: config });
    await login(session);
    await check('only selected navigation appears; browser modules are lazy', "document.querySelectorAll('#plugin-navigation button').length===5&&!document.querySelector('#plugin-navigation').textContent.includes('未选')&&!window.__panelPlugin");
    await click('[data-page="plugin:example.panel.library"]');
    await wait(() => evaluate(`Boolean(${library}?.querySelector('[data-library]')?.textContent.includes('2 个流程'))`), 'actual Core library read');
    await check('page uses actual Core storage, immutable session and no credentials or arbitrary operations', "window.__panelPlugin.contexts[0].session.rootId&&Object.isFrozen(window.__panelPlugin.contexts[0].session)&&!('accessToken' in window.__panelPlugin.contexts[0].session)&&!('callOperation' in window.__panelPlugin.contexts[0])&&!window.__panelPlugin.contexts[0].api.providers");
    await check('Shadow DOM confines plugin CSS and inherits the Iris palette', `getComputedStyle(document.body).display!=='none'&&getComputedStyle(${library}.querySelector('.palette')).backgroundImage.includes('105deg')`);
    await capture('plugin-page-light'); await measure('plugin-page-wide');
    await click('#appearance-open');
    await evaluate("(()=>{const n=document.querySelector('#appearance-theme');n.value='dark';n.dispatchEvent(new Event('input',{bubbles:true}));})()");
    await click('#appearance-close');
    await wait(() => evaluate(`${library}?.querySelector('.plugin-content').dataset.theme==='dark'`), 'shared theme subscription');
    await check('live theme update does not remount the page or expose background data', "window.__panelPlugin.events.filter(e=>e==='library:mount').length===1&&window.__panelPlugin.contexts[0].theme.current().mode==='dark'&&!('background' in window.__panelPlugin.contexts[0].theme.current())");
    await capture('plugin-page-dark'); await dimensions(390, 844); await measure('plugin-page-mobile'); await capture('plugin-page-mobile'); await dimensions(1366, 900);
    await click('[data-page="plugin-settings"]');
    await check('leaving a page aborts/cleans it; settings start folded', "window.__panelPlugin.events.includes('library:abort')&&window.__panelPlugin.events.includes('library:cleanup')&&[...document.querySelectorAll('#plugin-settings-list details')].every(n=>!n.open)&&!document.querySelector('#plugin-settings-list .plugin-surface')");
    await click('#plugin-settings-list summary');
    await wait(() => evaluate(`Boolean(${settings}?.querySelector('form'))`), 'actual settings read');
    await evaluate(`(()=>{const root=${settings};root.querySelector('input').value='Panel saved service';root.querySelector('form').requestSubmit();})()`);
    await wait(() => evaluate(`${settings}?.querySelector('[data-settings-status]')?.textContent==='已保存 · Panel saved service'`), 'actual settings saved');
    assert.equal((await executeConfigCommand(config, 'settings.show')).providers[0].name, 'Panel saved service');
    result.checks.push('settings persists real configuration through the revision-checked Core Provider API'); save();
    await capture('plugin-settings-dark');
    await click('[data-page="plugin:example.panel.library"]');
    await wait(() => evaluate(`Boolean(${library}?.querySelector('[data-library]')?.textContent.includes('2 个流程'))`), 'library remount');
    await click('[data-page="plugin-settings"]');
    await wait(() => evaluate(`${settings}?.querySelector('input')?.value==='Panel saved service'`), 'saved settings re-read');
    await check('mounts share session identity; Provider methods belong only to settings mounts', "window.__panelPlugin.contexts.every(c=>c.session===window.__panelPlugin.contexts[0].session)&&window.__panelPlugin.contexts.filter(c=>c.dependency.kind==='settings').every(c=>Boolean(c.api.providers))");
    await click('#studio-tab'); await click('#plugin-preview>summary');
    await evaluate("(()=>{const n=document.querySelector('#plugin-renderer');n.value='example.panel.png';n.dispatchEvent(new Event('change',{bubbles:true}));})()");
    await wait(() => evaluate(`Boolean(${preview}?.querySelector('[data-preview-info]'))`), 'renderer original bytes');
    await check('MIME-selected renderer displays real Artifact pixels alongside native preview', `window.__panelPlugin.preview.mediaType==='image/png'&&window.__panelPlugin.preview.size===${FLOW_RESULT.length}&&${preview}.querySelector('img').naturalWidth===48&&!document.querySelector('#output-image').hidden`);
    const actualHash = await evaluate("(async()=>{const c=window.__panelPlugin.contexts.find(c=>c.artifact);const b=await c.api.artifact(c.artifact);return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await b.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('')})()");
    assert.equal(actualHash, createHash('sha256').update(FLOW_RESULT).digest('hex'));
    result.checks.push('authenticated renderer bytes equal the original Core image hash without resubmission'); save();
    await capture('plugin-renderer-dark');
    await click('#plugin-preview>summary');
    await wait(() => evaluate("window.__panelPlugin.events.includes('png:cleanup')&&!document.querySelector('#plugin-preview-slot .plugin-surface')"), 'renderer cleanup');
    await check('closing preview revokes its scoped API', "(async()=>{const c=window.__panelPlugin.contexts.find(c=>c.artifact);try{await c.api.artifact(c.artifact);return false}catch(e){return c.signal.aborted&&e.name==='AbortError'}})()");
    await click('[data-page="plugin:example.panel.slow"]');
    await wait(() => evaluate("window.__panelPlugin.events.includes('slow:mount')"), 'slow mount pending');
    await click('[data-page="plugin:example.panel.library"]'); await evaluate('window.__panelPlugin.resumeSlow()');
    await wait(() => evaluate("window.__panelPlugin.events.includes('slow:cleanup')"), 'late cleanup');
    await check('late completion is detached, cleans once and cannot issue a new Core read', "(async()=>{const e=window.__panelPlugin,c=e.contexts.find(c=>c.dependency.contributionId==='example.panel.slow');try{await c.api.runs();return false}catch(error){return error.name==='AbortError'&&e.events.filter(e=>e==='slow:cleanup').length===1&&!document.querySelector('#plugin-page-slot').textContent.includes('旧挂载')}})()");
    await click('[data-page="plugin:example.panel.broken"]');
    await wait(() => evaluate("document.querySelector('#plugin-page-slot [data-code=IRIS_PLUGIN_WEB_MOUNT]')?.textContent.includes('Controlled mount failure')"), 'locatable mount error');
    await check('failed mount reports contribution and phase while shell remains usable', "document.querySelector('#plugin-page-slot').textContent.includes('example.panel.broken')&&!document.querySelector('#workspace-nav').hidden");
    await click('[data-page="plugin:example.panel.module"]');
    await wait(() => evaluate("document.querySelector('#plugin-page-slot [data-code=IRIS_PLUGIN_WEB_MODULE]')?.textContent.includes('mount(context)')"), 'module contract error');
    result.checks.push('a module missing its mount export is diagnosed at the module stage'); save();
    await cdp('Fetch.enable', { patterns: [{ urlPattern: session.origin + '*/pages/example.panel.library/web/style.css', requestStage: 'Request' }] });
    await click('[data-page="plugin:example.panel.library"]');
    await wait(() => pausedResponses.length > 0, 'controlled stylesheet failure');
    await cdp('Fetch.failRequest', { requestId: pausedResponses.shift(), errorReason: 'Failed' }); await cdp('Fetch.disable');
    await wait(() => evaluate("document.querySelector('#plugin-page-slot [data-code=IRIS_PLUGIN_WEB_STYLES]')?.textContent.includes('example.panel.library')"), 'style error');
    result.checks.push('failed stylesheet load reports exact contribution and styles phase without importing another plugin'); save();
    await click('#studio-tab');
    await click('[data-page="plugin:example.panel.library"]');
    await wait(() => evaluate(`Boolean(${library}?.querySelector('[data-library]')?.textContent.includes('2 个流程'))`), 'page recovery');
    await evaluate('window.__panelPlugin.failCleanup=true'); await click('#studio-tab');
    await wait(() => evaluate("document.querySelector('#plugin-feedback').dataset.code==='IRIS_PLUGIN_WEB_CLEANUP'&&!document.querySelector('#plugin-feedback').hidden"), 'cleanup failure reported');
    await check('cleanup failure remains visible while container and API are still revoked', "document.querySelector('#plugin-feedback').textContent.includes('Controlled cleanup failure')&&!document.querySelector('#plugin-page-slot .plugin-surface')");
    await evaluate('window.__panelPlugin.failCleanup=false');
    await click('[data-page="plugin:example.panel.library"]');
    await wait(() => evaluate(`Boolean(${library}?.querySelector('[data-library]')?.textContent.includes('2 个流程'))`), 'page after cleanup error');
    await click('#disconnect');
    await wait(() => evaluate("!document.querySelector('#connection').hidden&&window.__panelPlugin.contexts.every(c=>c.signal.aborted)"), 'logout revokes contexts');
    await check('logout clears navigation/mounts and rejects retained API contexts', "(async()=>{try{await window.__panelPlugin.contexts.at(-1).api.runs();return false}catch(e){return e.name==='AbortError'&&document.querySelector('#plugin-navigation').hidden&&!document.querySelector('.plugin-surface')}})()");
    // Only this probe's isolated service is restarted; user preview and data are untouched.
    session = await restart({ pluginRegistry: registry, panelContributions: selection }); await login(session);
    await click('[data-page="plugin-settings"]'); await click('#plugin-settings-list summary');
    await wait(() => evaluate(`${settings}?.querySelector('[data-settings-status]')?.textContent==='此会话未开启供应商设置'`), 'read-only settings');
    await check('a read-only owner cannot acquire Provider write methods through the mount', "!window.__panelPlugin.contexts[0].api.providers&&window.__panelPlugin.contexts[0].session.providerManagement===false");
    assert.equal((await executeConfigCommand(config, 'settings.show')).providers[0].name, 'Panel saved service');
    assert(!report.requests.some(item => item.url.includes('/pages/example.panel.hidden/')));
    const requestsBefore = report.requests.length;
    session = await restart({}); await login(session);
    await check('a legacy session without Panel contributions logs in and reads its Run without requesting new script or style routes', "!window.__panelPlugin&&document.querySelector('#plugin-navigation').hidden&&!document.querySelector('#run-view').hidden");
    assert(!report.requests.slice(requestsBefore).some(item => /\/(plugin-panel\.js|plugin-surface\.css)(?:[?#]|$)/.test(item.url)));
    result.status = 'passed'; save();
  } finally { await registry.dispose(); }
}
